using System.Security.Cryptography;using Microsoft.Extensions.Logging;namespace RandomNumbersApi.Services{public class RandomNumberService : IRandomNumberService{private readonly ILogger<RandomNumberService> _logger;public RandomNumberService(ILogger<RandomNumberService> logger){_logger = logger;}public int[] GetTwoRandomNumbers(int minInclusive, int maxInclusive){if(minInclusive > maxInclusive){throw new ArgumentException("minInclusive cannot be greater than maxInclusive");}_logger.LogDebug("Generating two random numbers between {Min} and {Max}.", minInclusive, maxInclusive);int a = RandomNumberGenerator.GetInt32(minInclusive, checked(maxInclusive + 1));int b = RandomNumberGenerator.GetInt32(minInclusive, checked(maxInclusive + 1));return new[]{a,b};}}}